<script setup>
import { computed, onMounted, ref } from 'vue'
import { getCustomerParcels } from '../../api/parcels'
import { normalizeApiError } from '../../utils/apiError'
import { formatDateTime, formatRelativeExpiry, isPickupWindowOpen } from '../../utils/format'
import PageHeader from '../../components/PageHeader.vue'
import LoadingState from '../../components/LoadingState.vue'
import ErrorState from '../../components/ErrorState.vue'
import EmptyState from '../../components/EmptyState.vue'
import CustomerParcelList from '../../components/CustomerParcelList.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import AppIcon from '../../components/AppIcon.vue'

const parcels=ref([]);const loading=ref(true);const errorMessage=ref('')
const counts=computed(()=>({ready:parcels.value.filter(p=>isPickupWindowOpen(p)).length,pickedUp:parcels.value.filter(p=>p.status==='PICKED_UP').length,expired:parcels.value.filter(p=>p.status==='EXPIRED'||(p.status==='STORED'&&!isPickupWindowOpen(p))).length}))
const readyParcels=computed(()=>parcels.value.filter(p=>isPickupWindowOpen(p)).sort((left,right)=>Date.parse(left.expiresAt)-Date.parse(right.expiresAt)))
const nextExpiring=computed(()=>readyParcels.value[0]||null)
async function load(){loading.value=true;errorMessage.value='';try{parcels.value=await getCustomerParcels()}catch(error){errorMessage.value=normalizeApiError(error,'包裹数据加载失败').message}finally{loading.value=false}}
onMounted(load)
</script>

<template><section><PageHeader title="用户工作台" eyebrow="用户" description="查看当前账号的待取件包裹和历史记录。"><RouterLink class="btn-primary" to="/customer/parcels">查看我的包裹 <AppIcon name="arrow" :size="16"/></RouterLink></PageHeader><LoadingState v-if="loading" class="mt-6"/><ErrorState v-else-if="errorMessage" class="mt-6" :message="errorMessage" @retry="load"/><div v-else class="mt-6 space-y-6"><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-12"><article class="panel surface-brand p-6 sm:col-span-2 xl:col-span-8"><div class="flex items-start justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-[.15em] text-[var(--color-brand-deep)]">待取件</p><p class="metric-number mt-3 text-5xl font-black">{{counts.ready}}</p><p class="mt-2 text-sm text-[var(--color-ink-700)]">当前仍在有效取件时间内的包裹</p></div><span class="grid size-12 place-items-center rounded-2xl bg-white/70 text-[var(--color-brand)] shadow-[var(--shadow-sm)]"><AppIcon name="locker" :size="25"/></span></div><div v-if="nextExpiring" class="mt-6 rounded-[var(--radius-sm)] border border-white/80 bg-white/65 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-[.12em] text-[var(--color-ink-500)]">即将到期的包裹</p><p class="tracking-code mt-1">{{nextExpiring.trackingNumber}}</p></div><StatusBadge :status="nextExpiring.status"/></div><dl class="mt-4 grid grid-cols-2 gap-4 text-sm"><div><dt>快递柜站点</dt><dd>{{nextExpiring.stationName||'暂未分配'}}</dd></div><div><dt>柜格</dt><dd class="text-lg">{{nextExpiring.lockerCellCode||'—'}}</dd></div><div class="col-span-2"><dt>取件截止时间</dt><dd>{{formatDateTime(nextExpiring.expiresAt)}}</dd><p class="expiry-relative mt-1">{{formatRelativeExpiry(nextExpiring.expiresAt)}}</p></div></dl><RouterLink class="btn-primary mt-4" to="/customer/parcels">输入取件码 <AppIcon name="arrow" :size="16"/></RouterLink></div><div v-else class="mt-6 rounded-[var(--radius-sm)] border border-dashed border-[var(--color-line)] bg-white/45 p-4 text-sm text-[var(--color-ink-500)]">当前没有可取件的包裹。</div></article><article v-for="item in [{label:'已取件',value:counts.pickedUp,note:'已完成取件',color:'var(--color-info)'},{label:'已过期',value:counts.expired,note:'已超过取件时间',color:'var(--color-warning)'}]" :key="item.label" class="panel metric-card p-5 xl:col-span-4"><span class="block h-1 w-8 rounded-full" :style="{background:item.color}"></span><p class="mt-4 text-xs font-bold uppercase tracking-[.1em] text-[var(--color-ink-500)]">{{item.label}}</p><p class="metric-number mt-2 text-3xl font-black">{{item.value}}</p><p class="mt-2 text-xs text-[var(--color-ink-500)]">{{item.note}}</p></article></div><div><div class="mb-4 flex items-center justify-between"><div><p class="text-[10px] font-bold uppercase tracking-[.14em] text-[var(--color-brand)]">包裹记录</p><h2 class="mt-1 text-lg font-black">最近包裹</h2></div><RouterLink v-if="parcels.length" class="section-link" to="/customer/parcels">查看全部 <AppIcon name="arrow" :size="15"/></RouterLink></div><EmptyState v-if="!parcels.length" message="快递员为你存入包裹后，包裹将显示在这里。"/><CustomerParcelList v-else :parcels="parcels.slice(0,4)" @pickup="$router.push('/customer/parcels')"/></div></div></section></template>
